// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import NewsFilters from "../index";

const navigation = vi.hoisted(() => ({ replace: vi.fn() }));
vi.mock("next/navigation", () => ({
  useRouter: () => ({ replace: navigation.replace }),
  usePathname: () => "/fr/news/page/2",
  useSearchParams: () =>
    new URLSearchParams("tag=java,temurin&source=adoptium&page=2"),
}));
vi.mock("next-intl", async () => {
  const actual = await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    ...actual,
    useTranslations: (namespace: "ModernPages.news") =>
      actual.createTranslator({ locale: "en", messages, namespace }),
  };
});

beforeEach(() => {
  vi.useFakeTimers();
  navigation.replace.mockClear();
});
afterEach(() => {
  vi.clearAllTimers();
  vi.useRealTimers();
});

describe("News filters", () => {
  const props = {
    tags: [
      { value: "java", label: "Java" },
      { value: "temurin", label: "Temurin" },
    ],
    authors: [],
  };

  it("opens a filter from the keyboard and clears all tags while retaining locale and source", () => {
    render(<NewsFilters {...props} />);
    fireEvent.keyDown(screen.getByRole("combobox", { name: "All tags" }), {
      key: "Enter",
    });
    expect(screen.getByRole("textbox", { name: "All tags" })).toHaveFocus();
    fireEvent.click(screen.getByRole("option", { name: "All tags" }));
    expect(navigation.replace).toHaveBeenCalledWith("/fr/news?source=adoptium");
  });

  it("removes one tag without dropping the remaining filter", () => {
    render(<NewsFilters {...props} />);
    fireEvent.click(screen.getByRole("button", { name: "Remove tag: java" }));
    expect(navigation.replace).toHaveBeenCalledWith(
      "/fr/news?tag=temurin&source=adoptium",
    );
  });
});
